# The `update_playlist` API only supports updating the playlist title or privacy, not modifying its songs.
# I will check if there is an API to update the songs in a playlist or to remove songs from a playlist.
# I will look for any API with "song" and "playlist" in the name or description.
for api in apis.api_docs.show_api_descriptions(app_name='spotify'):
    if 'song' in api['name'] and 'playlist' in api['name']:
        print(api)

