steps.code:
# The search_songs API already returns the release_date for the song.
# So I can directly extract the release month from the release_date field.
# I will now do this for all songs in songs_to_update list.

from datetime import datetime

def extract_release_month(release_date_str):
    dt = datetime.fromisoformat(release_date_str)
    return dt.strftime("%m/%Y")

release_months = {}
for song_title, artist in songs_to_update:
    query = f"{song_title} {artist}"
    search_result = apis.spotify.search_songs(query=query, page_limit=1)
    if search_result:
        release_date = search_result[0].get("release_date")
        if release_date:
            release_month = extract_release_month(release_date)
            release_months[(song_title, artist)] = release_month
        else:
            release_months[(song_title, artist)] = None
    else:
        release_months[(song_title, artist)] = None

print(release_months)  # Dictionary with (song_title, artist) as key and release month as value.

